static void aw_Capacitor2_process_fast(void *aw_state, int16_t *aw_out,
    const int16_t *aw_in, int32_t sampleFrames, uint32_t aw_channels) {
    aw_Capacitor2_fast_t *aw_s = (aw_Capacitor2_fast_t *)aw_state;
    const double aw_sample_rate = aw_s->aw_sample_rate;
    (void)aw_sample_rate;
    float iirHighpassAL = aw_s->iirHighpassAL;
    float iirHighpassBL = aw_s->iirHighpassBL;
    float iirHighpassCL = aw_s->iirHighpassCL;
    float iirHighpassDL = aw_s->iirHighpassDL;
    float iirHighpassEL = aw_s->iirHighpassEL;
    float iirHighpassFL = aw_s->iirHighpassFL;
    float iirLowpassAL = aw_s->iirLowpassAL;
    float iirLowpassBL = aw_s->iirLowpassBL;
    float iirLowpassCL = aw_s->iirLowpassCL;
    float iirLowpassDL = aw_s->iirLowpassDL;
    float iirLowpassEL = aw_s->iirLowpassEL;
    float iirLowpassFL = aw_s->iirLowpassFL;
    float iirHighpassAR = aw_s->iirHighpassAR;
    float iirHighpassBR = aw_s->iirHighpassBR;
    float iirHighpassCR = aw_s->iirHighpassCR;
    float iirHighpassDR = aw_s->iirHighpassDR;
    float iirHighpassER = aw_s->iirHighpassER;
    float iirHighpassFR = aw_s->iirHighpassFR;
    float iirLowpassAR = aw_s->iirLowpassAR;
    float iirLowpassBR = aw_s->iirLowpassBR;
    float iirLowpassCR = aw_s->iirLowpassCR;
    float iirLowpassDR = aw_s->iirLowpassDR;
    float iirLowpassER = aw_s->iirLowpassER;
    float iirLowpassFR = aw_s->iirLowpassFR;
    int count = aw_s->count;
    float lowpassChase = aw_s->lowpassChase;
    float highpassChase = aw_s->highpassChase;
    float wetChase = aw_s->wetChase;
    float lowpassBaseAmount = aw_s->lowpassBaseAmount;
    float highpassBaseAmount = aw_s->highpassBaseAmount;
    float wet = aw_s->wet;
    float lastLowpass = aw_s->lastLowpass;
    float lastHighpass = aw_s->lastHighpass;
    float lastWet = aw_s->lastWet;
    uint32_t fpdL = aw_s->fpdL;
    uint32_t fpdR = aw_s->fpdR;
    float A = aw_s->A;
    float B = aw_s->B;
    float C = aw_s->C;
    float D = aw_s->D;
    {

	lowpassChase = pow(A,2);
	highpassChase = pow(B,2);
	double nonLin = 1.0+((1.0-C)*6.0);
	double nonLinTrim = 1.5/cbrt(nonLin);
	wetChase = D;
	//should not scale with sample rate, because values reaching 1 are important
	//to its ability to bypass when set to max
	double lowpassSpeed = 300 / (fabs( lastLowpass - lowpassChase)+1.0);
	double highpassSpeed = 300 / (fabs( lastHighpass - highpassChase)+1.0);
	double wetSpeed = 300 / (fabs( lastWet - wetChase)+1.0);
	lastLowpass = lowpassChase;
	lastHighpass = highpassChase;
	lastWet = wetChase;
	    
    const float aw_f_nonLin = (float)nonLin;
	const float aw_f_nonLinTrim = (float)nonLinTrim;
	const float aw_f_lowpassSpeed = (float)lowpassSpeed;
	const float aw_f_highpassSpeed = (float)highpassSpeed;
	const float aw_f_wetSpeed = (float)wetSpeed;
	const float aw_inv0 = 1.0f / (aw_f_nonLin);
	const float aw_inv1 = 1.0f / ((aw_f_lowpassSpeed + 1.0f));
	const float aw_inv2 = 1.0f / ((aw_f_highpassSpeed + 1.0f));
	const float aw_inv3 = 1.0f / ((aw_f_wetSpeed+1.0f));
	while (--sampleFrames >= 0)
    {
		const float aw_inL = AW_IN_L(aw_in);
		const float aw_inR = AW_IN_R(aw_in, aw_channels);
		float aw_outL = 0.0f, aw_outR = 0.0f;/* aw:loop */
		float inputSampleL = aw_inL;
		float inputSampleR = aw_inR;
		if (fabsf(inputSampleL)<1.18e-23f) inputSampleL = fpdL * 1.18e-17f;
		if (fabsf(inputSampleR)<1.18e-23f) inputSampleR = fpdR * 1.18e-17f;
		float drySampleL = inputSampleL;
		float drySampleR = inputSampleR;
		
		float dielectricScaleL = fabsf(2.0f-((inputSampleL+aw_f_nonLin)* aw_inv0));
		float dielectricScaleR = fabsf(2.0f-((inputSampleR+aw_f_nonLin)* aw_inv0));
		
		lowpassBaseAmount = (((lowpassBaseAmount*aw_f_lowpassSpeed)+lowpassChase)* aw_inv1);
		//positive voltage will mean lower capacitance when capacitor is barium titanate
		//on the lowpass, higher pressure means positive swings/smaller cap/larger value for lowpassAmount
		float lowpassAmountL = lowpassBaseAmount * dielectricScaleL;
		float invLowpassL = 1.0f - lowpassAmountL;
		float lowpassAmountR = lowpassBaseAmount * dielectricScaleR;
		float invLowpassR = 1.0f - lowpassAmountR;
		
		highpassBaseAmount = (((highpassBaseAmount*aw_f_highpassSpeed)+highpassChase)* aw_inv2);
		//positive voltage will mean lower capacitance when capacitor is barium titanate
		//on the highpass, higher pressure means positive swings/smaller cap/larger value for highpassAmount
		float highpassAmountL = highpassBaseAmount * dielectricScaleL;
		float invHighpassL = 1.0f - highpassAmountL;
		float highpassAmountR = highpassBaseAmount * dielectricScaleR;
		float invHighpassR = 1.0f - highpassAmountR;
		
		wet = (((wet*aw_f_wetSpeed)+wetChase)* aw_inv3);
		
		count++; if (count > 5) count = 0; switch (count)
		{
			case 0:
				iirHighpassAL = (iirHighpassAL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassAL;
				iirHighpassBL = (iirHighpassBL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassBL;
				iirLowpassBL = (iirLowpassBL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassBL;
				iirHighpassDL = (iirHighpassDL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassDL;
				iirLowpassDL = (iirLowpassDL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassDL;
				iirHighpassAR = (iirHighpassAR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassAR;
				iirHighpassBR = (iirHighpassBR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassBR;
				iirLowpassBR = (iirLowpassBR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassBR;
				iirHighpassDR = (iirHighpassDR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassDR;
				iirLowpassDR = (iirLowpassDR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassDR;
				break;
			case 1:
				iirHighpassAL = (iirHighpassAL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassAL;
				iirHighpassCL = (iirHighpassCL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassCL;
				iirLowpassCL = (iirLowpassCL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassCL;
				iirHighpassEL = (iirHighpassEL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassEL;
				iirLowpassEL = (iirLowpassEL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassEL;
				iirHighpassAR = (iirHighpassAR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassAR;
				iirHighpassCR = (iirHighpassCR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassCR;
				iirLowpassCR = (iirLowpassCR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassCR;
				iirHighpassER = (iirHighpassER * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassER;
				iirLowpassER = (iirLowpassER * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassER;
				break;
			case 2:
				iirHighpassAL = (iirHighpassAL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassAL;
				iirHighpassBL = (iirHighpassBL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassBL;
				iirLowpassBL = (iirLowpassBL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassBL;
				iirHighpassFL = (iirHighpassFL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassFL;
				iirLowpassFL = (iirLowpassFL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassFL;
				iirHighpassAR = (iirHighpassAR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassAR;
				iirHighpassBR = (iirHighpassBR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassBR;
				iirLowpassBR = (iirLowpassBR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassBR;
				iirHighpassFR = (iirHighpassFR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassFR;
				iirLowpassFR = (iirLowpassFR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassFR;
				break;
			case 3:
				iirHighpassAL = (iirHighpassAL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassAL;
				iirHighpassCL = (iirHighpassCL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassCL;
				iirLowpassCL = (iirLowpassCL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassCL;
				iirHighpassDL = (iirHighpassDL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassDL;
				iirLowpassDL = (iirLowpassDL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassDL;
				iirHighpassAR = (iirHighpassAR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassAR;
				iirHighpassCR = (iirHighpassCR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassCR;
				iirLowpassCR = (iirLowpassCR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassCR;
				iirHighpassDR = (iirHighpassDR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassDR;
				iirLowpassDR = (iirLowpassDR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassDR;
				break;
			case 4:
				iirHighpassAL = (iirHighpassAL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassAL;
				iirHighpassBL = (iirHighpassBL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassBL;
				iirLowpassBL = (iirLowpassBL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassBL;
				iirHighpassEL = (iirHighpassEL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassEL;
				iirLowpassEL = (iirLowpassEL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassEL;
				iirHighpassAR = (iirHighpassAR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassAR;
				iirHighpassBR = (iirHighpassBR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassBR;
				iirLowpassBR = (iirLowpassBR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassBR;
				iirHighpassER = (iirHighpassER * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassER;
				iirLowpassER = (iirLowpassER * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassER;
				break;
			case 5:
				iirHighpassAL = (iirHighpassAL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassAL;
				iirLowpassAL = (iirLowpassAL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassAL;
				iirHighpassCL = (iirHighpassCL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassCL;
				iirLowpassCL = (iirLowpassCL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassCL;
				iirHighpassFL = (iirHighpassFL * invHighpassL) + (inputSampleL * highpassAmountL); inputSampleL -= iirHighpassFL;
				iirLowpassFL = (iirLowpassFL * invLowpassL) + (inputSampleL * lowpassAmountL); inputSampleL = iirLowpassFL;
				iirHighpassAR = (iirHighpassAR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassAR;
				iirLowpassAR = (iirLowpassAR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassAR;
				iirHighpassCR = (iirHighpassCR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassCR;
				iirLowpassCR = (iirLowpassCR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassCR;
				iirHighpassFR = (iirHighpassFR * invHighpassR) + (inputSampleR * highpassAmountR); inputSampleR -= iirHighpassFR;
				iirLowpassFR = (iirLowpassFR * invLowpassR) + (inputSampleR * lowpassAmountR); inputSampleR = iirLowpassFR;
				break;
		}
		//Highpass Filter chunk. This is three poles of IIR highpass, with a 'gearbox' that progressively
		//steepens the filter after minimizing artifacts.
		
		inputSampleL = (drySampleL * (1.0f-wet)) + (inputSampleL * aw_f_nonLinTrim * wet);
		inputSampleR = (drySampleR * (1.0f-wet)) + (inputSampleR * aw_f_nonLinTrim * wet);
		fpdL ^= fpdL << 13; fpdL ^= fpdL >> 17; fpdL ^= fpdL << 5;
		fpdR ^= fpdR << 13; fpdR ^= fpdR >> 17; fpdR ^= fpdR << 5;
		//end 32 bit stereo floating point dither
		
		aw_outL = inputSampleL;
		aw_outR = inputSampleR;
    /* aw:end */		AW_OUT_FAST(aw_out, aw_channels, aw_outL, aw_outR);
		aw_in += aw_channels;
		aw_out += aw_channels;
	}
}
    aw_s->iirHighpassAL = iirHighpassAL;
    aw_s->iirHighpassBL = iirHighpassBL;
    aw_s->iirHighpassCL = iirHighpassCL;
    aw_s->iirHighpassDL = iirHighpassDL;
    aw_s->iirHighpassEL = iirHighpassEL;
    aw_s->iirHighpassFL = iirHighpassFL;
    aw_s->iirLowpassAL = iirLowpassAL;
    aw_s->iirLowpassBL = iirLowpassBL;
    aw_s->iirLowpassCL = iirLowpassCL;
    aw_s->iirLowpassDL = iirLowpassDL;
    aw_s->iirLowpassEL = iirLowpassEL;
    aw_s->iirLowpassFL = iirLowpassFL;
    aw_s->iirHighpassAR = iirHighpassAR;
    aw_s->iirHighpassBR = iirHighpassBR;
    aw_s->iirHighpassCR = iirHighpassCR;
    aw_s->iirHighpassDR = iirHighpassDR;
    aw_s->iirHighpassER = iirHighpassER;
    aw_s->iirHighpassFR = iirHighpassFR;
    aw_s->iirLowpassAR = iirLowpassAR;
    aw_s->iirLowpassBR = iirLowpassBR;
    aw_s->iirLowpassCR = iirLowpassCR;
    aw_s->iirLowpassDR = iirLowpassDR;
    aw_s->iirLowpassER = iirLowpassER;
    aw_s->iirLowpassFR = iirLowpassFR;
    aw_s->count = count;
    aw_s->lowpassChase = lowpassChase;
    aw_s->highpassChase = highpassChase;
    aw_s->wetChase = wetChase;
    aw_s->lowpassBaseAmount = lowpassBaseAmount;
    aw_s->highpassBaseAmount = highpassBaseAmount;
    aw_s->wet = wet;
    aw_s->lastLowpass = lastLowpass;
    aw_s->lastHighpass = lastHighpass;
    aw_s->lastWet = lastWet;
    aw_s->fpdL = fpdL;
    aw_s->fpdR = fpdR;
}

